        "##### 合并检验 #####\n",
        "from scipy import stats\n",
        "\n",
        "p = g.pivot_table(index=[\"dist_idx\", \"seed\"], columns=\"cap_idx\", values=\"gap\")\n",
        "delta = (p[4] - p[3]).groupby(\"seed\").mean()        # 每个种子：五个距离平均后的变化\n",
        "t, pv = stats.ttest_1samp(delta, 0)\n",
        "se = delta.std() / np.sqrt(len(delta))\n",
        "print(\"各种子的变化：\", delta.round(4).tolist())\n",
        "print(\"均值\", round(delta.mean(), 4), \"| t =\", round(t, 2), \"| p =\", round(pv, 4))\n",
        "print(\"95% 置信区间：\", round(delta.mean() - stats.t.ppf(.975, 4) * se, 4),\n",
        "      \"到\", round(delta.mean() + stats.t.ppf(.975, 4) * se, 4))"
